module household.process;
use household.quiet_hours.{NoiseEvent, violation};
use household.policy.notice_note;
use std.date.Date;
use std.types.Result;
use legal.time.counted_calendar_deadline;

query notice_deadline(event: NoiseEvent) -> Date { scope = true; applies = violation(event); meta = notice_note; }
rule seven_days for notice_deadline(event) { when = true; yield = counted_calendar_deadline(event.on, 7, false); meta = notice_note; }
enum NoticeState { Pending, Delivered }
enum TransitionError { NoEstablishedDuty, LateDelivery, AlreadyDelivered }
type NoticeEvent = { delivered_on: Date, due_on: Date, duty_established: Bool };
fn deliver_notice(state: NoticeState, event: NoticeEvent) -> Result<NoticeState, TransitionError> {
    if not event.duty_established { Result.Err(TransitionError.NoEstablishedDuty) }
    else if state == NoticeState.Delivered { Result.Err(TransitionError.AlreadyDelivered) }
    else if event.delivered_on > event.due_on { Result.Err(TransitionError.LateDelivery) }
    else { Result.Ok(NoticeState.Delivered) }
}

module household.quiet_hours;
use std.date.{Date, date};
use legal.time.in_force;
use household.policy.{policy_v1, policy_v2, policy_note, ordinary_note, emergency_note, revision_note};

enum NoiseStatus { Permitted, Prohibited }
type NoiseEvent = { on: Date, member: Bool, after_hours: Bool, emergency: Bool, approved_event: Bool };
query noise_status(event: NoiseEvent) -> NoiseStatus {
    scope = true;
    applies = event.member and event.after_hours and event.on >= date(2029, 1, 1);
    meta = policy_note;
}
rule ordinary_v1 for noise_status(event) { when = in_force(policy_v1.lifecycle, event.on); yield = NoiseStatus.Prohibited; meta = ordinary_note; }
rule ordinary_v2 for noise_status(event) { when = in_force(policy_v2.lifecycle, event.on); yield = NoiseStatus.Prohibited; meta = revision_note; }
rule emergency_v1 for noise_status(event) { when = in_force(policy_v1.lifecycle, event.on) and event.emergency; yield = NoiseStatus.Permitted; meta = emergency_note; }
rule emergency_v2 for noise_status(event) { when = in_force(policy_v2.lifecycle, event.on) and event.emergency; yield = NoiseStatus.Permitted; meta = emergency_note; }
rule approved_event_v2 for noise_status(event) { when = in_force(policy_v2.lifecycle, event.on) and event.approved_event; yield = NoiseStatus.Permitted; meta = revision_note; }
priority emergency_v1_priority for noise_status(event) { higher = emergency_v1; lower = ordinary_v1; when = true; meta = emergency_note; }
priority emergency_v2_priority for noise_status(event) { higher = emergency_v2; lower = ordinary_v2; when = true; meta = emergency_note; }
priority event_v2_priority for noise_status(event) { higher = approved_event_v2; lower = ordinary_v2; when = true; meta = revision_note; }

query violation(event: NoiseEvent) -> Bool { scope = true; applies = event.member and event.after_hours and event.on >= date(2029,1,1); meta = policy_note; }
rule determine_violation for violation(event) { when = true; yield = noise_status(event) == NoiseStatus.Prohibited; meta = policy_note; }

query fine_amount(event: NoiseEvent) -> Rational { scope = true; applies = event.member and event.on >= date(2029,1,1); meta = policy_note; }
// Deliberately no fine rule. A violation cannot invent a remedy.

// Fictional competing interpretations, separate from the authored policy above.
query synthetic_conflict(first: Bool, second: Bool) -> NoiseStatus { scope = true; applies = true; meta = policy_note; }
rule synthetic_permission for synthetic_conflict(first, second) { when = first; yield = NoiseStatus.Permitted; }
rule synthetic_prohibition for synthetic_conflict(first, second) { when = second; yield = NoiseStatus.Prohibited; }

module us.authority;
use std.date.Date;
use std.types.Option;
use legal.model.{OpinionRole, Publication, Institution};
use legal.time.authority_available;
use us.authority.sources.{vertical_note, ninth_note, coverage};

const supreme_court = Institution { id: "us.scotus", description: "Supreme Court of the United States", jurisdiction: "United States; competence is question-specific" };
const ninth_circuit = Institution { id: "us.ca9", description: "United States Court of Appeals for the Ninth Circuit", jurisdiction: "Federal appellate jurisdiction; not a geographic parent of households" };
enum CourtProfile { SupremeCourtInFederalLowerCourt, NinthCircuitInCircuitFederalCourt, Other }
type AuthorityContext = {
    profile: CourtProfile, role: OpinionRole, publication: Publication, issued_on: Date,
    historical_cutoff: Option<Date>, accepted_holding: Bool, materially_applicable: Bool,
    treatment_leaves_proposition_controlling: Bool, citation_permitted_under_applicable_rules: Bool,
    accepted_persuasive_relevance: Bool
};
fn supported_profile(context: AuthorityContext) -> Bool { context.profile != CourtProfile.Other }
query binding(context: AuthorityContext) -> Bool {
    scope = supported_profile(context)
        and (context.role == OpinionRole.Majority or context.role == OpinionRole.Concurrence or context.role == OpinionRole.Dissent)
        and (context.profile != CourtProfile.NinthCircuitInCircuitFederalCourt or context.publication != Publication.Unknown);
    applies = authority_available(context.issued_on, context.historical_cutoff);
    meta = vertical_note;
}
rule supreme_court_holding for binding(context) {
    when = context.profile == CourtProfile.SupremeCourtInFederalLowerCourt;
    yield = context.role == OpinionRole.Majority and context.accepted_holding and context.materially_applicable and context.treatment_leaves_proposition_controlling;
    meta = vertical_note;
}
rule ninth_published_holding for binding(context) {
    when = context.profile == CourtProfile.NinthCircuitInCircuitFederalCourt;
    yield = context.publication == Publication.Published and context.role == OpinionRole.Majority and context.accepted_holding and context.materially_applicable and context.treatment_leaves_proposition_controlling;
    meta = ninth_note;
}
query citation_permission(context: AuthorityContext) -> Bool { scope = supported_profile(context); applies = authority_available(context.issued_on, context.historical_cutoff); meta = ninth_note; }
rule supplied_citation_analysis for citation_permission(context) { when = true; yield = context.citation_permitted_under_applicable_rules; meta = ninth_note; }
query persuasive_relevance(context: AuthorityContext) -> Bool { scope = supported_profile(context); applies = authority_available(context.issued_on, context.historical_cutoff); meta = vertical_note; }
rule supplied_relevance_analysis for persuasive_relevance(context) { when = true; yield = context.accepted_persuasive_relevance; meta = vertical_note; }

